    pub fn split(&self,span_max:u64) -> Vec<Span> {
        if span_max == 0 || self.len() <= span_max {
            return vec![self.clone()];
        }

        let mut spans = Vec::new();
        let mut current_start = self.start;
        let mut current_end = self.start;

        for &file in &self.files {
            let file_entry = &pending[file];
            let end = file_entry.offset + file_entry.size;

            if end - current_start > span_max {
                spans.push(Span {
                    start:current_start,
                    end:current_end,
                    files:self.files.clone(),
                });
                current_start = end;
                current_end = end;
            } else {
                current_end = end;
            }
        }

        if current_start < self.end {
            spans.push(Span {
                start:current_start,
                end:self.end,
                files:self.files.clone(),
            });
        }

        spans
